/* Self-contained visual asset fallback. Generated for GitHub Pages reliability.
   It does not alter game logic. It replaces broken image URLs with embedded art. */
(function(){
  "use strict";
  const ART = {"ref-title":"data:image/webp;base64,","garrick":"data:image/webp;base64,","elowen":"data:image/webp;base64,","pip":"data:image/webp;base64,","aldren":"data:image/webp;base64,","rowan":"data:image/webp;base64,","cedric":"data:image/webp;base64,","keep-panorama":"data:image/webp;base64,","yard":"data:image/webp;base64,","library":"data:image/webp;base64,","garden":"data:image/webp;base64,","forge":"data:image/webp;base64,","stables":"data:image/webp;base64,","chapel":"data:image/webp;base64,","campfire":"data:image/webp;base64,","garrick-cedric":"data:image/webp;base64,","investiture":"data:image/webp;base64,","journal-memory":"data:image/webp;base64,","hero":"data:image/webp;base64,"};
  function keyFrom(value){
    if(!value || value.startsWith("data:")) return null;
    const clean=value.split("?")[0].split("#")[0];
    const file=clean.substring(clean.lastIndexOf("/")+1);
    return file.replace(/\.(svg|png|jpg|jpeg|webp)$/i,"");
  }
  function patchImage(img){
    const key=keyFrom(img.getAttribute("src")||"");
    if(key && ART[key] && img.src!==ART[key]) img.src=ART[key];
  }
  function patchTree(node){
    if(!node) return;
    if(node.nodeType===1 && node.tagName==="IMG") patchImage(node);
    if(node.querySelectorAll) node.querySelectorAll("img").forEach(patchImage);
  }
  function installChoiceArt(){
    const s=document.createElement("style");
    s.id="embedded-choice-art";
    s.textContent=`
      .choice-button:nth-child(1)::before{background-image:url("${ART.yard}")!important}
      .choice-button:nth-child(2)::before{background-image:url("${ART.library}")!important}
      .choice-button:nth-child(3)::before{background-image:url("${ART.garden}")!important}
    `;
    document.head.appendChild(s);
  }
  installChoiceArt();
  const observer=new MutationObserver(records=>{
    for(const record of records){
      if(record.type==="attributes" && record.target.tagName==="IMG") patchImage(record.target);
      record.addedNodes && record.addedNodes.forEach(patchTree);
    }
  });
  observer.observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:["src"]});
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",()=>patchTree(document));
  else patchTree(document);
})();
